418	package net.officefloor.hq.app.sheet;
419	
420	import java.time.LocalDate;
421	import net.officefloor.hq.app.rollup.RollupService;
422	import org.springframework.dao.DataIntegrityViolationException;
423	import org.springframework.stereotype.Service;
424	import org.springframework.transaction.annotation.Transactional;
425	
426	/**
427	 * Loads a sheet by id, starting an empty one the first time the id is used, and keeps the sheet's
428	 * today. The real clock is read only once, to give a new sheet its starting today; everything else
429	 * dated uses {@link #today(String)}.
430	 */
431	@Service
432	public class SheetService {
433	
434	    private final SheetRepository sheets;
435	    private final RollupService rollup;
436	
437	    public SheetService(SheetRepository sheets, RollupService rollup) {
438	        this.sheets = sheets;
439	        this.rollup = rollup;
440	    }
441	
442	    public Sheet load(String id, String user) {
443	        return sheets.findById(id).orElseGet(() -> start(id, user));
444	    }
445	
446	    public Sheet get(String id) {
447	        return sheets.findById(id).orElseThrow(() -> new SheetNotFoundException(id));
448	    }
449	
450	    /** The sheet's today: use it for every date-dependent decision and default date. */
451	    public LocalDate today(String id) {
452	        return sheets.findById(id).map(Sheet::getToday).orElseThrow(() -> new SheetNotFoundException(id));
453	    }
454	
455	    /** Change the sheet's today; it has no audit record of its own, only the figures it moves. */
456	    @Transactional
457	    public Sheet setToday(String id, String user, LocalDate today) {
458	        Sheet sheet = sheets.findById(id).orElseThrow(() -> new SheetNotFoundException(id));
459	        RollupService.Snapshot before = rollup.snapshot(id);
460	        sheet.setToday(today);
461	        Sheet saved = sheets.saveAndFlush(sheet);
462	        rollup.recordChanges(id, user, before);
463	        return saved;
464	    }
465	
466	    /**
467	     * The next claim number on the sheet: 1 for the first, then 2, and so on. The sheet's row is
468	     * locked until the caller's transaction ends, so two claims opened at once get different numbers.
469	     */
470	    @Transactional
471	    public long nextClaimNumber(String id) {
472	        if (sheets.incrementLastClaimNumber(id) != 1) {
473	            throw new SheetNotFoundException(id);
474	        }
475	        return sheets.lastClaimNumber(id);
476	    }
477	
478	    /**
479	     * The next place in the sheet's claim lists: a claim with a later place is listed before one with an earlier
480	     * place. The sheet's row is locked until the caller's transaction ends.
481	     */
482	    @Transactional
483	    public long nextListed(String id) {
484	        if (sheets.incrementLastListed(id) != 1) {
485	            throw new SheetNotFoundException(id);
486	        }
487	        return sheets.lastListed(id);
488	    }
489	
490	    /**
491	     * The next number in a sequence of its own on the sheet (a period's, or X for no period): the key, a dash, then
492	     * 1 for the first, then 2, and so on. The sheet's row is locked until the caller's transaction ends.
493	     */
494	    @Transactional
495	    public String nextSequenceNumber(String id, String key) {
496	        if (sheets.lockById(id) != 1) {
497	            throw new SheetNotFoundException(id);
498	        }
499	        sheets.incrementSequence(id, key);
500	        return key + "-" + sheets.lastSequenceNumber(id, key);
501	    }
502	
503	    private Sheet start(String id, String user) {
504	        try {
505	            return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now()));
506	        } catch (DataIntegrityViolationException e) {
507	            // Another user started the same sheet at the same moment: it exists now.
508	            return sheets.findById(id).orElseThrow(() -> e);
509	        }
510	    }
511	}
