539	/** A sheet: everything else in the app is kept per sheet. */
540	@Entity
541	@Table(name = "sheet")
542	public class Sheet {
543	
544	    /** The keys of the dated settings: each value is kept from its from-date. */
545	    public static final String CLERK_LIMIT = "clerk-limit";
546	    public static final String FLOOR = "floor";
547	    public static final String TERMS = "terms";
548	    public static final String LATE_PCT = "late-pct";
549	    public static final String CAP = "cap";
550	    public static final String PROOF_THRESHOLD = "proof-threshold";
551	
552	    /** The actions the permission matrix decides, each with the roles that may take it when its entry is blank. */
553	    public static final Map<String, String> STANDING_PERMISSIONS = Map.of("open", "clerk,steward", "settle",
554	            "clerk,steward", "void", "clerk,steward", "reassign", "steward", "close", "clerk,steward", "reopen",
555	            "steward");
556	    public static final List<String> PERMISSION_ACTIONS = List.of("open", "settle", "void", "reassign", "close",
557	            "reopen");
558	
559	    /** The sheet's starting values, in force before a key's first from-date: none for a key not listed. */
560	    private static final Map<String, String> STARTING = Map.of(FLOOR, "1.00", TERMS, "14", LATE_PCT, "0.00");
561	
562	    @Id
563	    private String id;
564	
565	    @Column(name = "created_by", nullable = false)
566	    private String createdBy;
567	
568	    /** The sheet's own today: every date-dependent decision and default date uses it. */
569	    @Column(name = "today", nullable = false)
570	    private LocalDate today;
571	
572	    /** The values of the dated settings (the clerk limit, the floor, the terms and each grade's, the late percent,
573	     *  the cap and the proof threshold), each from its from-date. */
574	    @OneToMany(mappedBy = "sheet", fetch = FetchType.EAGER, cascade = CascadeType.ALL)
575	    @OrderBy("key ASC, fromDate ASC")
576	    private List<DatedSetting> dated = new ArrayList<>();
577	
578	    /** The permission matrix: the roles (comma separated) that may take each action; an action left out keeps the
579	     *  standing rule. Not dated. */
580	    @ElementCollection(fetch = FetchType.EAGER)
581	    @CollectionTable(name = "sheet_permission", joinColumns = @JoinColumn(name = "sheet_id"))
582	    @MapKeyColumn(name = "action")
583	    @Column(name = "roles", nullable = false)
584	    private Map<String, String> permissions = new HashMap<>();
585	
586	    /** The policy date: a claim dated before it rounds half up, one on or after it half to even; null: the today. */
587	    @Column(name = "policy_date")
588	    private LocalDate policyDate;
589	
590	    /** From this date (on the sheet's today) a claim opened is numbered within its period; null: off. */
591	    @Column(name = "period_numbering_from")
592	    private LocalDate periodNumberingFrom;
593	
594	    protected Sheet() {
595	    }
596	
597	    public Sheet(String id, String createdBy, LocalDate today) {
598	        this.id = id;
599	        this.createdBy = createdBy;
600	        this.today = today;
601	    }
602	
603	    public String getId() {
604	        return id;
605	    }
606	
607	    public String getCreatedBy() {
608	        return createdBy;
609	    }
610	
611	    public LocalDate getToday() {
612	        return today;
613	    }
614	
615	    public void setToday(LocalDate today) {
616	        this.today = today;
617	    }
618	
619	    /** The key of a grade's own terms. */
620	    public static String gradeTermsKey(String grade) {
621	        return TERMS + "-" + grade;
622	    }
623	
624	    /**
625	     * Record a dated setting's value from the date (null: no limit or cap), replacing the value already recorded from
626	     * that date; the other values recorded are kept.
627	     */
628	    public void record(String key, LocalDate from, String value) {
629	        dated.stream().filter(d -> d.getKey().equals(key) && d.getFromDate().equals(from)).findFirst()
630	                .ifPresentOrElse(d -> d.setValue(value), () -> dated.add(new DatedSetting(this, key, from, value)));
631	    }
632	
633	    /** Each dated setting's recorded values by key, from-date first to last. */
634	    public Map<String, List<DatedSetting>> datedSettings() {
635	        Map<String, List<DatedSetting>> byKey = new TreeMap<>();
636	        dated.stream().sorted(Comparator.comparing(DatedSetting::getFromDate))
637	                .forEach(d -> byKey.computeIfAbsent(d.getKey(), k -> new ArrayList<>()).add(d));
638	        return byKey;
639	    }
640	
641	    /**
642	     * The value of a dated setting in force on the date: the one with the latest from-date on or before it, else the
643	     * sheet's starting value; empty when that is none.
644	     */
645	    public Optional<String> valueOn(String key, LocalDate date) {
646	        return dated.stream()
647	                .filter(d -> d.getKey().equals(key) && !d.getFromDate().isAfter(date))
648	                .max(Comparator.comparing(DatedSetting::getFromDate))
649	                .map(d -> Optional.ofNullable(d.getValue()))
650	                .orElseGet(() -> Optional.ofNullable(STARTING.get(key)));
651	    }
652	
653	    private Optional<BigDecimal> decimalOn(String key, LocalDate date) {
654	        return valueOn(key, date).map(v -> new BigDecimal(v).setScale(2, RoundingMode.UNNECESSARY));
655	    }
656	
657	    /** The highest due a clerk may settle, in force on the sheet's today; null when there is no limit. */
658	    public BigDecimal getClerkLimit() {
659	        return decimalOn(CLERK_LIMIT, today).orElse(null);
660	    }
661	
662	    /** The least a live due of a claim dated on the date can be. */
663	    public BigDecimal floorOn(LocalDate date) {
664	        return decimalOn(FLOOR, date).orElseThrow();
665	    }
666	
667	    /** The most a person's due-total can be, in force on the sheet's today; null when there is no cap. */
668	    public BigDecimal getCap() {
669	        return decimalOn(CAP, today).orElse(null);
670	    }
671	
672	    /**
673	     * The due above which a claim dated on the date cannot be settled or approved without a proof; null when there is
674	     * no threshold then.
675	     */
676	    public BigDecimal proofThresholdOn(LocalDate date) {
677	        return decimalOn(PROOF_THRESHOLD, date).orElse(null);
678	    }
679	
680	    /** The days after its date a claim dated on the date of a grade without its own terms then is due by. */
681	    public int termsOn(LocalDate date) {
682	        return Integer.parseInt(valueOn(TERMS, date).orElseThrow());
683	    }
684	
685	    /** The grade's own terms in force on the date; empty when it has none then (the sheet's terms apply). */
686	    public Optional<Integer> gradeTermsOn(String grade, LocalDate date) {
687	        return valueOn(gradeTermsKey(grade), date).map(Integer::parseInt);
688	    }
689	
690	    /** The days after its date a claim dated on the date of a person of the grade is due by. */
691	    public int termsFor(String grade, LocalDate date) {
692	        return gradeTermsOn(grade, date).orElseGet(() -> termsOn(date));
693	    }
694	
695	    /** The percent of its figure an overdue claim dated on the date gains for every full 30 days it is overdue. */
696	    public BigDecimal latePctOn(LocalDate date) {
697	        return decimalOn(LATE_PCT, date).orElseThrow();
698	    }
699	
700	    /** The roles entered for the action, comma separated; null when blank (the standing rule applies). */
701	    public String permission(String action) {
702	        return permissions.get(action);
703	    }
704	
705	    /** Enter the roles that may take the action; null or blank keeps the standing rule. */
706	    public void setPermission(String action, String roles) {
707	        if (roles == null || roles.isBlank()) {
708	            permissions.remove(action);
709	        } else {
710	            permissions.put(action, roles);
711	        }
712	    }
713	
714	    /** Whether the role (clerk or steward) may take the action: as entered in the matrix, else the standing rule. */
715	    public boolean allows(String action, String role) {
716	        String roles = permissions.getOrDefault(action, STANDING_PERMISSIONS.get(action));
717	        return roles != null && Arrays.stream(roles.split(",")).map(String::trim).anyMatch(role::equals);
718	    }
719	
720	    public LocalDate getPolicyDate() {
721	        return policyDate;
722	    }
723	
724	    public void setPolicyDate(LocalDate policyDate) {
725	        this.policyDate = policyDate;
726	    }
727	
728	    public LocalDate getPeriodNumberingFrom() {
729	        return periodNumberingFrom;
730	    }
731	
732	    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
733	        this.periodNumberingFrom = periodNumberingFrom;
734	    }
735	
736	    /** Whether a claim opened now is numbered within its period: the setting is a date and today is on or after it. */
737	    public boolean numbersByPeriod() {
738	        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
739	    }
740	
741	    /**
742	     * How a claim rounding by {@code date} rounds its live figures: half up when dated before the policy date (the
743	     * sheet's today when it has none), half to even on or after it.
744	     */
745	    public RoundingMode rounding(LocalDate date) {
746	        return date.isBefore(policyDate != null ? policyDate : today) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
747	    }
748	
749	    /** The rate step: the amount at the percent, to two decimals rounded as a claim rounding by the date does. */
750	    public BigDecimal rateStep(BigDecimal amount, BigDecimal pct, LocalDate roundingDate) {
751	        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding(roundingDate));
752	    }
753	
754	    /**
755	     * The late charge on a figure of an OPEN claim dated {@code date}: the late percent of the figure for every full
756	     * 30 days the sheet's today is past the claim's due-by (the late percent in force on its date), rounded as the
757	     * claim's date has it; zero when not overdue,
758	     * null (n/a) when the figure is.
759	     */
760	    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate date) {
761	        if (figure == null) {
762	            return null;
763	        }
764	        long overdueDays = ChronoUnit.DAYS.between(dueBy, today);
765	        long periods = overdueDays <= 0 ? 0 : overdueDays / 30;
766	        return figure.multiply(latePctOn(date)).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
767	                .setScale(2, rounding(date));
768	    }
769	
770	    /** The figure with its late charge added on top when the claim is OPEN; null (n/a) stays null. */
771	    public BigDecimal withLateCharge(BigDecimal figure, boolean open, LocalDate dueBy, LocalDate date) {
772	        return figure == null || !open ? figure : figure.add(lateCharge(figure, dueBy, date));
773	    }
774	
775	    /** A due-total held down to the cap in force on the sheet's today; null (n/a), or no cap, leaves it as it is. */
776	    public BigDecimal capped(BigDecimal dueTotal) {
777	        BigDecimal cap = getCap();
778	        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
779	    }
780	
781	    /** A live due of a claim dated on the date raised to the floor in force on it; null (n/a) stays null. */
782	    public BigDecimal floored(BigDecimal due, LocalDate date) {
783	        return due == null ? null : due.max(floorOn(date));
784	    }
785	}
786	package net.officefloor.hq.app.period;
787	
788	import java.time.LocalDate;
789	import java.util.List;
790	import java.util.Optional;
791	import net.officefloor.hq.app.Audit;
792	import net.officefloor.hq.app.role.RoleService;
793	import net.officefloor.hq.app.rollup.RollupService;
794	import net.officefloor.hq.app.sheet.SheetNotFoundException;
795	import net.officefloor.hq.app.sheet.SheetRepository;
796	import org.springframework.dao.DataIntegrityViolationException;
797	import org.springframework.stereotype.Service;
798	import org.springframework.transaction.annotation.Transactional;
799	
800	/** Keeps the periods of each sheet: uniquely named, and no two overlapping; a closed period's claims are fixed. */
801	@Service
802	public class PeriodService {
803	
804	    private final PeriodRepository periods;
805	    private final SheetRepository sheets;
806	    private final Audit audit;
807	    private final RollupService rollup;
808	    private final RoleService roles;
809	
810	    public PeriodService(PeriodRepository periods, SheetRepository sheets, Audit audit, RollupService rollup,
811	            RoleService roles) {
812	        this.periods = periods;
813	        this.sheets = sheets;
814	        this.audit = audit;
815	        this.rollup = rollup;
816	        this.roles = roles;
817	    }
818	
819	    public List<Period> list(String sheetId) {
820	        return periods.findBySheetIdOrderByFromDateAscIdAsc(sheetId);
821	    }
822	
823	    /** Add a period; refused when its name is taken, its dates are reversed, or it overlaps another period. */
824	    @Transactional
825	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
826	        // Lock the sheet so two periods added at once are checked against each other.
827	        if (sheets.lockById(sheetId) == 0) {
828	            throw new SheetNotFoundException(sheetId);
829	        }
830	        if (to.isBefore(from)) {
831	            throw new PeriodRefusedException("The period " + name + " ends before it starts");
832	        }
833	        if (periods.existsBySheetIdAndName(sheetId, name)) {
834	            throw new PeriodRefusedException("The period name " + name + " is already in use on sheet " + sheetId);
835	        }
836	        if (list(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
837	            throw new PeriodRefusedException("The period " + name + " overlaps another period on sheet " + sheetId);
838	        }
839	        Period saved;
840	        try {
841	            saved = periods.saveAndFlush(new Period(sheetId, name, from, to));
842	        } catch (DataIntegrityViolationException e) {
843	            throw new PeriodRefusedException("The period name " + name + " is already in use on sheet " + sheetId);
844	        }
845	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
846	                + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
847	        return saved;
848	    }
849	
850	    /** Close a period, fixing every person's due-total for it, and so its own, as they are now; refused when it is already closed or the user's role may not close. */
851	    @Transactional
852	    public Period close(String sheetId, String user, String name) {
853	        // Lock the sheet so no claim in the period changes while its total is fixed.
854	        if (sheets.lockById(sheetId) == 0) {
855	            throw new SheetNotFoundException(sheetId);
856	        }
857	        Period period = periods.findBySheetIdAndName(sheetId, name)
858	                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
859	        if (!roles.may(sheetId, user, "close")) {
860	            throw new PeriodCloseForbiddenException(name, user);
861	        }
862	        if (period.isClosed()) {
863	            throw new PeriodClosedException(name);
864	        }
865	        period.close(rollup.dueTotalsBetween(sheetId, period.getFromDate(), period.getToDate()));
866	        Period saved = periods.saveAndFlush(period);
867	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
868	                + " total=" + saved.getClosedTotal().toPlainString());
869	        return saved;
870	    }
871	
872	    /** Reopen a closed period, making its due-total live again; refused unless the user's role may reopen and it is closed. */
873	    @Transactional
874	    public Period reopen(String sheetId, String user, String name) {
875	        if (sheets.lockById(sheetId) == 0) {
876	            throw new SheetNotFoundException(sheetId);
877	        }
878	        Period period = periods.findBySheetIdAndName(sheetId, name)
879	                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
880	        if (!roles.may(sheetId, user, "reopen")) {
881	            throw new PeriodReopenForbiddenException(name, user);
882	        }
883	        if (!period.isClosed()) {
884	            throw new PeriodNotClosedException(name);
885	        }
886	        period.reopen();
887	        Period saved = periods.saveAndFlush(period);
888	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
889	        return saved;
890	    }
891	
892	    /** The name of the period the date falls in; empty when it is in none. */
893	    public Optional<String> nameOn(String sheetId, LocalDate date) {
894	        return list(sheetId).stream().filter(p -> p.contains(date)).map(Period::getName).findFirst();
895	    }
896	
897	    /**
898	     * Refuse a change to a claim dated on any of the dates when one falls in a closed period. The sheet is locked
899	     * until the caller's transaction ends, so a period cannot close while the change is made.
900	     */
901	    @Transactional
902	    public void requireOpen(String sheetId, LocalDate... dates) {
903	        if (sheets.lockById(sheetId) == 0) {
904	            throw new SheetNotFoundException(sheetId);
905	        }
906	        for (Period period : list(sheetId)) {
907	            for (LocalDate date : dates) {
908	                if (period.isClosed() && period.contains(date)) {
909	                    throw new PeriodClosedException(period.getName(), date);
910	                }
911	            }
912	        }
913	    }
