package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Keeps the sheet's settings: its clerk limit, its floor, its terms and each grade's, its late percent, its cap and its proof threshold, each
 * dated (kept from a from-date); and its policy date, its period numbering from and its permission matrix, not dated.
 */
@Service
public class SettingService {

    /** The grades that may have their own terms. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;

    public SettingService(SheetRepository sheets, Audit audit, RollupService rollup) {
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    public Sheet get(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(() -> new SheetNotFoundException(sheetId));
    }

    /**
     * Set the clerk limit from the date (null: the sheet's today); a null limit means no limit. Every save is
     * recorded, even of the same value.
     */
    @Transactional
    public Sheet setClerkLimit(String sheetId, String user, BigDecimal limit, LocalDate from) {
        return record(sheetId, user, Sheet.CLERK_LIMIT, limit == null ? null : limit.toPlainString(), from, false);
    }

    /**
     * Set the floor, the least a live due of a claim dated from the date (null: the sheet's today) can be. Every save
     * is recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setFloor(String sheetId, String user, BigDecimal floor, LocalDate from) {
        return record(sheetId, user, Sheet.FLOOR, floor.toPlainString(), from, true);
    }

    /**
     * Set the terms from the date (null: the sheet's today), the days after its date a claim dated from then of a grade
     * without its own terms is due by. Every save is recorded, even of the same value. Claims already added keep their
     * due-by.
     */
    @Transactional
    public Sheet setTerms(String sheetId, String user, int terms, LocalDate from) {
        return record(sheetId, user, Sheet.TERMS, String.valueOf(terms), from, false);
    }

    /** The grades with their own terms in force on the sheet's today, in grade order; a grade not in it uses the sheet's terms. */
    public Map<String, Integer> gradeTerms(Sheet sheet) {
        Map<String, Integer> terms = new LinkedHashMap<>();
        for (String grade : GRADES) {
            sheet.gradeTermsOn(grade, sheet.getToday()).ifPresent(t -> terms.put(grade, t));
        }
        return terms;
    }

    /** The terms in force for a claim dated on the date of a person of the grade: the grade's own, else the sheet's. */
    public int termsFor(String sheetId, String grade, LocalDate date) {
        return get(sheetId).termsFor(grade, date);
    }

    /**
     * Set a grade's own terms from the date (null: the sheet's today). Every save is recorded, even of the same value.
     * Claims already added keep their due-by.
     */
    @Transactional
    public Sheet setGradeTerms(String sheetId, String user, String grade, int terms, LocalDate from) {
        return record(sheetId, user, Sheet.gradeTermsKey(grade), String.valueOf(terms), from, false);
    }

    /**
     * Set the late percent from the date (null: the sheet's today), what an overdue claim dated from then gains for
     * every full 30 days it is overdue. Every save is recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setLatePct(String sheetId, String user, BigDecimal latePct, LocalDate from) {
        return record(sheetId, user, Sheet.LATE_PCT, latePct.toPlainString(), from, true);
    }

    /**
     * Set the cap from the date (null: the sheet's today), the most a person's due-total can be; a null cap means
     * none. Every save is recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setCap(String sheetId, String user, BigDecimal cap, LocalDate from) {
        return record(sheetId, user, Sheet.CAP, cap == null ? null : cap.toPlainString(), from, true);
    }

    /**
     * Set the proof threshold from the date (null: the sheet's today): a claim dated from then whose due is above it
     * cannot be settled or approved without a proof; a null threshold means none. Every save is recorded, even of the
     * same value.
     */
    @Transactional
    public Sheet setProofThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
        return record(sheetId, user, Sheet.PROOF_THRESHOLD, threshold == null ? null : threshold.toPlainString(), from,
                false);
    }

    /**
     * Record a dated setting's value from the date (null: the sheet's today), replacing one recorded from that date,
     * then the SETTING_CHANGED record (with the from-date when one was given) and, when the setting moves figures,
     * the figures it moved.
     */
    private Sheet record(String sheetId, String user, String key, String value, LocalDate from, boolean movesFigures) {
        Sheet sheet = get(sheetId);
        RollupService.Snapshot before = movesFigures ? rollup.snapshot(sheetId) : null;
        sheet.record(key, from != null ? from : sheet.getToday(), value);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value="
                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
        if (movesFigures) {
            rollup.recordChanges(sheetId, user, before);
        }
        return saved;
    }
    /**
     * Set the policy date, which decides how each claim's live figures round; null means the sheet's today. Every save
     * is recorded, even of the same value, then the figures it moved.
     */
    @Transactional
    public Sheet setPolicyDate(String sheetId, String user, LocalDate policyDate) {
        Sheet sheet = get(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=policy-date value="
                + (policyDate == null ? "" : policyDate.toString()));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Set the roles (comma separated) that may take the action; null or blank keeps the standing rule. Every save is
     * recorded, even of the same value.
     */
    @Transactional
    public Sheet setPermission(String sheetId, String user, String action, String roles) {
        Sheet sheet = get(sheetId);
        sheet.setPermission(action, roles);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=perm-" + action + " value="
                + (roles == null ? "" : roles));
        return saved;
    }

    /**
     * Set the period numbering from; null means off. Every save is recorded, even of the same value. Claims already
     * opened keep their numbers.
     */
    @Transactional
    public Sheet setPeriodNumberingFrom(String sheetId, String user, LocalDate from) {
        Sheet sheet = get(sheetId);
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=period-numbering-from value="
                + (from == null ? "" : from.toString()));
        return saved;
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The sheet's settings. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/settings")
@Validated
public class SettingController {

    /**
     * The settings as shown, each dated one as in force on the sheet's today: the clerk limit with two decimals, null
     * when there is none; the floor with two decimals; the terms in whole days; each grade's own terms in whole days,
     * by grade (a grade without its own is left out); the late percent with two decimals; the policy date as
     * yyyy-mm-dd, null when blank (the sheet's today); the period numbering from as yyyy-mm-dd, null when blank (off);
     * the cap with two decimals, null when there is none; the proof threshold with two decimals, null when there is none;
     * the permission matrix, by action (open, settle, void, reassign, close, reopen), the roles entered for it comma
     * separated, null when blank (the standing rule).
     * Then every value recorded of each dated setting, by key (clerk-limit, floor, terms, terms-A, terms-B, terms-C,
     * late-pct, cap, proof-threshold), from-date first to last.
     */
    public record SettingsView(String clerkLimit, String floor, int terms, Map<String, Integer> gradeTerms,
            String latePct, LocalDate policyDate, LocalDate periodNumberingFrom, String cap,
            String proofThreshold, Map<String, String> permissions, Map<String, List<DatedValue>> dated) {

        static SettingsView of(Sheet sheet, Map<String, Integer> gradeTerms) {
            LocalDate today = sheet.getToday();
            Map<String, List<DatedValue>> dated = new LinkedHashMap<>();
            sheet.datedSettings().forEach((key, values) -> dated.put(key,
                    values.stream().map(d -> new DatedValue(d.getFromDate(), d.getValue())).toList()));
            Map<String, String> permissions = new LinkedHashMap<>();
            Sheet.PERMISSION_ACTIONS.forEach(action -> permissions.put(action, sheet.permission(action)));
            return new SettingsView(shown(sheet.getClerkLimit()), shown(sheet.floorOn(today)), sheet.termsOn(today),
                    gradeTerms, shown(sheet.latePctOn(today)), sheet.getPolicyDate(), sheet.getPeriodNumberingFrom(),
                    shown(sheet.getCap()), shown(sheet.proofThresholdOn(today)), permissions, dated);
        }

        private static String shown(BigDecimal value) {
            return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
        }
    }

    /** A dated setting's value (null: none) from its from-date. */
    public record DatedValue(LocalDate from, String value) {
    }

    /**
     * A clerk limit of 0.00 or more with up to two decimals, blank or missing meaning no limit, from the date (missing:
     * the sheet's today).
     */
    public record SettingsRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String clerkLimit,
            LocalDate from) {

        BigDecimal clerkLimitValue() {
            return clerkLimit == null || clerkLimit.isBlank() ? null
                    : new BigDecimal(clerkLimit.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** A floor of 0.00 or more with up to two decimals, from the date (missing: the sheet's today). */
    public record FloorRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String floor,
            LocalDate from) {

        BigDecimal floorValue() {
            return new BigDecimal(floor.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** Terms of 0 or more whole days, from the date (missing: the sheet's today). */
    public record TermsRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,5}\\s*") String terms,
            LocalDate from) {

        int termsValue() {
            return Integer.parseInt(terms.trim());
        }
    }

    /** A late percent of 0.00 or more with up to two decimals, from the date (missing: the sheet's today). */
    public record LatePctRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String latePct,
            LocalDate from) {

        BigDecimal latePctValue() {
            return new BigDecimal(latePct.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /**
     * A cap of 0.00 or more with up to two decimals, blank or missing meaning no cap, from the date (missing: the
     * sheet's today).
     */
    public record CapRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String cap,
            LocalDate from) {

        BigDecimal capValue() {
            return cap == null || cap.isBlank() ? null
                    : new BigDecimal(cap.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /**
     * A proof threshold of 0.00 or more with up to two decimals, blank or missing meaning none, from the date
     * (missing: the sheet's today).
     */
    public record ProofThresholdRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String proofThreshold,
            LocalDate from) {

        BigDecimal proofThresholdValue() {
            return proofThreshold == null || proofThreshold.isBlank() ? null
                    : new BigDecimal(proofThreshold.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** The roles that may take an action, comma separated (clerk, steward); blank or missing keeps the standing rule. */
    public record PermissionRequest(
            @Pattern(regexp = "\\s*((clerk|steward)(\\s*,\\s*(clerk|steward))*)?\\s*") String roles) {

        String rolesValue() {
            return roles == null || roles.isBlank() ? null : roles.replaceAll("\\s", "");
        }
    }

    /** A policy date as yyyy-mm-dd; null (blank) means the sheet's today. */
    public record PolicyDateRequest(LocalDate policyDate) {
    }

    /** A period numbering from as yyyy-mm-dd; null (blank) means off. */
    public record PeriodNumberingFromRequest(LocalDate periodNumberingFrom) {
    }

    private final SettingService service;

    public SettingController(SettingService service) {
        this.service = service;
    }

    @GetMapping
    public SettingsView get(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.get(sheetId.trim()));
    }

    @PutMapping
    public SettingsView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid SettingsRequest request) {
        return view(service.setClerkLimit(sheetId.trim(), user.trim(), request.clerkLimitValue(), request.from()));
    }

    @PutMapping("/floor")
    public SettingsView setFloor(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid FloorRequest request) {
        return view(service.setFloor(sheetId.trim(), user.trim(), request.floorValue(), request.from()));
    }

    @PutMapping("/terms")
    public SettingsView setTerms(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid TermsRequest request) {
        return view(service.setTerms(sheetId.trim(), user.trim(), request.termsValue(), request.from()));
    }

    @PutMapping("/terms/{grade}")
    public SettingsView setGradeTerms(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid TermsRequest request) {
        return view(service.setGradeTerms(sheetId.trim(), user.trim(), grade, request.termsValue(), request.from()));
    }

    @PutMapping("/late-pct")
    public SettingsView setLatePct(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid LatePctRequest request) {
        return view(service.setLatePct(sheetId.trim(), user.trim(), request.latePctValue(), request.from()));
    }

    @PutMapping("/policy-date")
    public SettingsView setPolicyDate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody PolicyDateRequest request) {
        return view(service.setPolicyDate(sheetId.trim(), user.trim(), request.policyDate()));
    }

    @PutMapping("/period-numbering-from")
    public SettingsView setPeriodNumberingFrom(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody PeriodNumberingFromRequest request) {
        return view(service.setPeriodNumberingFrom(sheetId.trim(), user.trim(), request.periodNumberingFrom()));
    }

    @PutMapping("/cap")
    public SettingsView setCap(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid CapRequest request) {
        return view(service.setCap(sheetId.trim(), user.trim(), request.capValue(), request.from()));
    }

    @PutMapping("/proof-threshold")
    public SettingsView setProofThreshold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ProofThresholdRequest request) {
        return view(service.setProofThreshold(sheetId.trim(), user.trim(), request.proofThresholdValue(),
                request.from()));
    }

    @PutMapping("/perm/{action}")
    public SettingsView setPermission(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "open|settle|void|reassign|close|reopen") String action,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PermissionRequest request) {
        return view(service.setPermission(sheetId.trim(), user.trim(), action, request.rolesValue()));
    }

    private SettingsView view(Sheet sheet) {
        return SettingsView.of(sheet, service.gradeTerms(sheet));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Loads a sheet by id, starting an empty one the first time the id is used, and keeps the sheet's
 * today. The real clock is read only once, to give a new sheet its starting today; everything else
 * dated uses {@link #today(String)}.
 */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;

    public SheetService(SheetRepository sheets, RollupService rollup) {
        this.sheets = sheets;
        this.rollup = rollup;
    }

    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> start(id, user));
    }

    public Sheet get(String id) {
        return sheets.findById(id).orElseThrow(() -> new SheetNotFoundException(id));
    }

    /** The sheet's today: use it for every date-dependent decision and default date. */
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseThrow(() -> new SheetNotFoundException(id));
    }

    /** Change the sheet's today; it has no audit record of its own, only the figures it moves. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = sheets.findById(id).orElseThrow(() -> new SheetNotFoundException(id));
        RollupService.Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        rollup.recordChanges(id, user, before);
        return saved;
    }

    /**
     * The next claim number on the sheet: 1 for the first, then 2, and so on. The sheet's row is
     * locked until the caller's transaction ends, so two claims opened at once get different numbers.
     */
    @Transactional
    public long nextClaimNumber(String id) {
        if (sheets.incrementLastClaimNumber(id) != 1) {
            throw new SheetNotFoundException(id);
        }
        return sheets.lastClaimNumber(id);
    }

    /**
     * The next place in the sheet's claim lists: a claim with a later place is listed before one with an earlier
     * place. The sheet's row is locked until the caller's transaction ends.
     */
    @Transactional
    public long nextListed(String id) {
        if (sheets.incrementLastListed(id) != 1) {
            throw new SheetNotFoundException(id);
        }
        return sheets.lastListed(id);
    }

    /**
     * The next number in a sequence of its own on the sheet (a period's, or X for no period): the key, a dash, then
     * 1 for the first, then 2, and so on. The sheet's row is locked until the caller's transaction ends.
     */
    @Transactional
    public String nextSequenceNumber(String id, String key) {
        if (sheets.lockById(id) != 1) {
            throw new SheetNotFoundException(id);
        }
        sheets.incrementSequence(id, key);
        return key + "-" + sheets.lastSequenceNumber(id, key);
    }

    private Sheet start(String id, String user) {
        try {
            return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now()));
        } catch (DataIntegrityViolationException e) {
            // Another user started the same sheet at the same moment: it exists now.
            return sheets.findById(id).orElseThrow(() -> e);
        }
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.CascadeType;
import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;

/** A sheet: everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The keys of the dated settings: each value is kept from its from-date. */
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String TERMS = "terms";
    public static final String LATE_PCT = "late-pct";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The actions the permission matrix decides, each with the roles that may take it when its entry is blank. */
    public static final Map<String, String> STANDING_PERMISSIONS = Map.of("open", "clerk,steward", "settle",
            "clerk,steward", "void", "clerk,steward", "reassign", "steward", "close", "clerk,steward", "reopen",
            "steward");
    public static final List<String> PERMISSION_ACTIONS = List.of("open", "settle", "void", "reassign", "close",
            "reopen");

    /** The sheet's starting values, in force before a key's first from-date: none for a key not listed. */
    private static final Map<String, String> STARTING = Map.of(FLOOR, "1.00", TERMS, "14", LATE_PCT, "0.00");

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    /** The sheet's own today: every date-dependent decision and default date uses it. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The values of the dated settings (the clerk limit, the floor, the terms and each grade's, the late percent,
     *  the cap and the proof threshold), each from its from-date. */
    @OneToMany(mappedBy = "sheet", fetch = FetchType.EAGER, cascade = CascadeType.ALL)
    @OrderBy("key ASC, fromDate ASC")
    private List<DatedSetting> dated = new ArrayList<>();

    /** The permission matrix: the roles (comma separated) that may take each action; an action left out keeps the
     *  standing rule. Not dated. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_permission", joinColumns = @JoinColumn(name = "sheet_id"))
    @MapKeyColumn(name = "action")
    @Column(name = "roles", nullable = false)
    private Map<String, String> permissions = new HashMap<>();

    /** The policy date: a claim dated before it rounds half up, one on or after it half to even; null: the today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** From this date (on the sheet's today) a claim opened is numbered within its period; null: off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    protected Sheet() {
    }

    public Sheet(String id, String createdBy, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.today = today;
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    /** The key of a grade's own terms. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /**
     * Record a dated setting's value from the date (null: no limit or cap), replacing the value already recorded from
     * that date; the other values recorded are kept.
     */
    public void record(String key, LocalDate from, String value) {
        dated.stream().filter(d -> d.getKey().equals(key) && d.getFromDate().equals(from)).findFirst()
                .ifPresentOrElse(d -> d.setValue(value), () -> dated.add(new DatedSetting(this, key, from, value)));
    }

    /** Each dated setting's recorded values by key, from-date first to last. */
    public Map<String, List<DatedSetting>> datedSettings() {
        Map<String, List<DatedSetting>> byKey = new TreeMap<>();
        dated.stream().sorted(Comparator.comparing(DatedSetting::getFromDate))
                .forEach(d -> byKey.computeIfAbsent(d.getKey(), k -> new ArrayList<>()).add(d));
        return byKey;
    }

    /**
     * The value of a dated setting in force on the date: the one with the latest from-date on or before it, else the
     * sheet's starting value; empty when that is none.
     */
    public Optional<String> valueOn(String key, LocalDate date) {
        return dated.stream()
                .filter(d -> d.getKey().equals(key) && !d.getFromDate().isAfter(date))
                .max(Comparator.comparing(DatedSetting::getFromDate))
                .map(d -> Optional.ofNullable(d.getValue()))
                .orElseGet(() -> Optional.ofNullable(STARTING.get(key)));
    }

    private Optional<BigDecimal> decimalOn(String key, LocalDate date) {
        return valueOn(key, date).map(v -> new BigDecimal(v).setScale(2, RoundingMode.UNNECESSARY));
    }

    /** The highest due a clerk may settle, in force on the sheet's today; null when there is no limit. */
    public BigDecimal getClerkLimit() {
        return decimalOn(CLERK_LIMIT, today).orElse(null);
    }

    /** The least a live due of a claim dated on the date can be. */
    public BigDecimal floorOn(LocalDate date) {
        return decimalOn(FLOOR, date).orElseThrow();
    }

    /** The most a person's due-total can be, in force on the sheet's today; null when there is no cap. */
    public BigDecimal getCap() {
        return decimalOn(CAP, today).orElse(null);
    }

    /**
     * The due above which a claim dated on the date cannot be settled or approved without a proof; null when there is
     * no threshold then.
     */
    public BigDecimal proofThresholdOn(LocalDate date) {
        return decimalOn(PROOF_THRESHOLD, date).orElse(null);
    }

    /** The days after its date a claim dated on the date of a grade without its own terms then is due by. */
    public int termsOn(LocalDate date) {
        return Integer.parseInt(valueOn(TERMS, date).orElseThrow());
    }

    /** The grade's own terms in force on the date; empty when it has none then (the sheet's terms apply). */
    public Optional<Integer> gradeTermsOn(String grade, LocalDate date) {
        return valueOn(gradeTermsKey(grade), date).map(Integer::parseInt);
    }

    /** The days after its date a claim dated on the date of a person of the grade is due by. */
    public int termsFor(String grade, LocalDate date) {
        return gradeTermsOn(grade, date).orElseGet(() -> termsOn(date));
    }

    /** The percent of its figure an overdue claim dated on the date gains for every full 30 days it is overdue. */
    public BigDecimal latePctOn(LocalDate date) {
        return decimalOn(LATE_PCT, date).orElseThrow();
    }

    /** The roles entered for the action, comma separated; null when blank (the standing rule applies). */
    public String permission(String action) {
        return permissions.get(action);
    }

    /** Enter the roles that may take the action; null or blank keeps the standing rule. */
    public void setPermission(String action, String roles) {
        if (roles == null || roles.isBlank()) {
            permissions.remove(action);
        } else {
            permissions.put(action, roles);
        }
    }

    /** Whether the role (clerk or steward) may take the action: as entered in the matrix, else the standing rule. */
    public boolean allows(String action, String role) {
        String roles = permissions.getOrDefault(action, STANDING_PERMISSIONS.get(action));
        return roles != null && Arrays.stream(roles.split(",")).map(String::trim).anyMatch(role::equals);
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /** Whether a claim opened now is numbered within its period: the setting is a date and today is on or after it. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /**
     * How a claim rounding by {@code date} rounds its live figures: half up when dated before the policy date (the
     * sheet's today when it has none), half to even on or after it.
     */
    public RoundingMode rounding(LocalDate date) {
        return date.isBefore(policyDate != null ? policyDate : today) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The rate step: the amount at the percent, to two decimals rounded as a claim rounding by the date does. */
    public BigDecimal rateStep(BigDecimal amount, BigDecimal pct, LocalDate roundingDate) {
        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding(roundingDate));
    }

    /**
     * The late charge on a figure of an OPEN claim dated {@code date}: the late percent of the figure for every full
     * 30 days the sheet's today is past the claim's due-by (the late percent in force on its date), rounded as the
     * claim's date has it; zero when not overdue,
     * null (n/a) when the figure is.
     */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate date) {
        if (figure == null) {
            return null;
        }
        long overdueDays = ChronoUnit.DAYS.between(dueBy, today);
        long periods = overdueDays <= 0 ? 0 : overdueDays / 30;
        return figure.multiply(latePctOn(date)).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, rounding(date));
    }

    /** The figure with its late charge added on top when the claim is OPEN; null (n/a) stays null. */
    public BigDecimal withLateCharge(BigDecimal figure, boolean open, LocalDate dueBy, LocalDate date) {
        return figure == null || !open ? figure : figure.add(lateCharge(figure, dueBy, date));
    }

    /** A due-total held down to the cap in force on the sheet's today; null (n/a), or no cap, leaves it as it is. */
    public BigDecimal capped(BigDecimal dueTotal) {
        BigDecimal cap = getCap();
        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
    }

    /** A live due of a claim dated on the date raised to the floor in force on it; null (n/a) stays null. */
    public BigDecimal floored(BigDecimal due, LocalDate date) {
        return due == null ? null : due.max(floorOn(date));
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps the periods of each sheet: uniquely named, and no two overlapping; a closed period's claims are fixed. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final RoleService roles;

    public PeriodService(PeriodRepository periods, SheetRepository sheets, Audit audit, RollupService rollup,
            RoleService roles) {
        this.periods = periods;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
        this.roles = roles;
    }

    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAscIdAsc(sheetId);
    }

    /** Add a period; refused when its name is taken, its dates are reversed, or it overlaps another period. */
    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        // Lock the sheet so two periods added at once are checked against each other.
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        if (to.isBefore(from)) {
            throw new PeriodRefusedException("The period " + name + " ends before it starts");
        }
        if (periods.existsBySheetIdAndName(sheetId, name)) {
            throw new PeriodRefusedException("The period name " + name + " is already in use on sheet " + sheetId);
        }
        if (list(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
            throw new PeriodRefusedException("The period " + name + " overlaps another period on sheet " + sheetId);
        }
        Period saved;
        try {
            saved = periods.saveAndFlush(new Period(sheetId, name, from, to));
        } catch (DataIntegrityViolationException e) {
            throw new PeriodRefusedException("The period name " + name + " is already in use on sheet " + sheetId);
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
        return saved;
    }

    /** Close a period, fixing every person's due-total for it, and so its own, as they are now; refused when it is already closed or the user's role may not close. */
    @Transactional
    public Period close(String sheetId, String user, String name) {
        // Lock the sheet so no claim in the period changes while its total is fixed.
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
        if (!roles.may(sheetId, user, "close")) {
            throw new PeriodCloseForbiddenException(name, user);
        }
        if (period.isClosed()) {
            throw new PeriodClosedException(name);
        }
        period.close(rollup.dueTotalsBetween(sheetId, period.getFromDate(), period.getToDate()));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedTotal().toPlainString());
        return saved;
    }

    /** Reopen a closed period, making its due-total live again; refused unless the user's role may reopen and it is closed. */
    @Transactional
    public Period reopen(String sheetId, String user, String name) {
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
        if (!roles.may(sheetId, user, "reopen")) {
            throw new PeriodReopenForbiddenException(name, user);
        }
        if (!period.isClosed()) {
            throw new PeriodNotClosedException(name);
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
        return saved;
    }

    /** The name of the period the date falls in; empty when it is in none. */
    public Optional<String> nameOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.contains(date)).map(Period::getName).findFirst();
    }

    /**
     * Refuse a change to a claim dated on any of the dates when one falls in a closed period. The sheet is locked
     * until the caller's transaction ends, so a period cannot close while the change is made.
     */
    @Transactional
    public void requireOpen(String sheetId, LocalDate... dates) {
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        for (Period period : list(sheetId)) {
            for (LocalDate date : dates) {
                if (period.isClosed() && period.contains(date)) {
                    throw new PeriodClosedException(period.getName(), date);
                }
            }
        }
    }
}

